  const ds=f.discoveryStatus;
  if (!ds) console.log('  discoveryStatus: ABSENT');
  else if (typeof ds!=='object') console.log('  discoveryStatus:', JSON.stringify(ds));
  else {
    for (const [k,v] of Object.entries(ds)) {
