  }
  console.log('  versions:', JSON.stringify(f.versions).slice(0,500));
  console.log('  codeChangedSinceBoot:', f.codeChangedSinceBoot ?? x.codeChangedSinceBoot ?? 'absent');
  console.log('  facts.models count:', Array.isArray(f.models)?f.models.length:'?');
  console.log('  facts.errors:', JSON.stringify(f.errors).slice(0,300));
}
