meta.args:
{"command":"node -e "
const c=require('/tmp/wpf-r49/catalogue.json');
console.log('top keys:', Object.keys(c).join(', '));
const models=c.models||[]; const q=c.quarantined||c.quarantine||[];
console.log('models:', models.length, '| quarantined:', q.length, '| updatedAtMs:', c.updatedAtMs);
const full=JSON.stringify(c);
console.log('test-fleet occurrences in full payload:', (full.match(/test-fleet/g)||[]).length);
const bare=models.filter(m=>{const id=m.id||m.modelId||''; return id.split('::').length===1;});
const prov=models.filter(m=>{const id=m.id||m.modelId||''; return id.split('::').length===2;});
console.log('bare (1-part):', bare.length, bare.slice(0,5).map(m=>m.id||m.modelId));
console.log('provider-form (2-part):', prov.length, prov.slice(0,5).map(m=>m.id||m.modelId));
const multi=models.filter(m=>!(Array.isArray(m.harnesses)&&m.harnesses.length===1));
console.log('harnesses.length!==1:', multi.length, multi.slice(0,5).map(m=>(m.id||m.modelId)+':'+JSON.stringify(m.harnesses)));
console.log('quarantined ids:', q.map(x=>x.id||x.modelId||JSON.stringify(x).slice(0,80)));
const ember=models.filter(m=>JSON.stringify(m).includes('muse-ember'));
console.log('muse-ember rows:', ember.length);
for (const m of ember.slice(0,6)) console.log('  ', m.id||m.modelId, '| runnerCount:', m.runnerCount, '| harnesses:', JSON.stringify(m.harnesses), '| runners:', JSON.stringify(m.runnerIds||m.runners||'').slice(0,120));
console.log('has muse::meta::test-fleet-model:', models.some(m=>(m.id||m.modelId)==='muse::meta::test-fleet-model'));
"","description":"Analyze catalogue hygiene"}

