let pass = 0, fail = 0;
const check = (name, cond) => { cond ? pass++ : (fail++, console.log('FAIL:', name)); console.log((cond ? 'ok' : 'FAIL') + ' - ' + name); };

const store = createFleetModelSnapshotStore({ filePath: null });
const rec = (models) => fleetRunnerRecord({ runnerId: 'probe-runner', models });
const id = 'muse::meta::probe-model-1';

// 1-3: advertised -> present, count 1, harness len 1
store.update(rec([{ id, harness: 'muse', confirmedCaps: ['serve'] }]));
let snap = store.read();
let row = snap.models.find((m) => m.id === id);
check('advertised present', !!row);
check('advertised count 1', row?.runnerCount === 1);
check('advertised harness len 1', row?.harnesses?.length === 1);

// 4-5: drop -> row stays at count 0, unverified
store.update(rec([]));
snap = store.read();
row = snap.models.find((m) => m.id === id);
check('dropped row persists', !!row);
check('dropped count 0', row?.runnerCount === 0);

// 6-8: remove -> true then false, gone
check('remove true', store.remove(id) === true);
check('remove again false', store.remove(id) === false);
check('removed gone', !store.read().models.find((m) => m.id === id));

// 9-10: re-advertise -> back at 1
store.update(rec([{ id, harness: 'muse', confirmedCaps: ['serve'] }]));
row = store.read().models.find((m) => m.id === id);
check('re-advertised back', !!row);
check('re-advertised count 1', row?.runnerCount === 1);

// 11-12: bare id -> quarantined, never in models
store.update(rec([{ id: 'bare-model', harness: 'muse', confirmedCaps: ['serve'] }]));
snap = store.read();
check('bare quarantined', (snap.quarantined || []).some((q) => (q.id || q.modelId || '').includes('bare-model')));
check('bare never in models', !snap.models.some((m) => m.id === 'bare-model'));

console.log(`RESULT: ${pass} pass, ${fail} fail`);
